import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

export const Schema = z.object({
  stat_data: z.object({
    角色属性: z.object({
      等级: z.coerce.number().prefault(1),
      位阶: z.coerce.number().prefault(0),
      以太感应: z.coerce.number().prefault(5),
      肉体韧性: z.coerce.number().prefault(10),
      精神阈值: z.coerce.number().prefault(100)
    }),
    因果锚点: z.object({
      绑定物品: z.string().prefault('尚未绑定'),
      当前词条: z.array(z.string()).prefault([]),   // ✅ 改这里
      因果能级: z.coerce.number().prefault(0),
      进化方向: z.string().prefault('待定')
    }),
    物品栏: z.array(z.string()).prefault([]),        // ✅ 改这里
    轮回记录: z.object({
      当前轮回次数: z.coerce.number().prefault(0),
      累计死因记录: z.array(z.string()).prefault([]), // ✅ 改这里
      _当前因果偏移度: z.coerce.number().prefault(0)
    })
  })
});

